<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout · Nodexa</title><style>*{box-sizing:border-box}body{margin:0;background:#050b0d;color:#edf7f5;font:14px Inter,system-ui}.wrap{max-width:980px;margin:36px auto;padding:18px}.grid{display:grid;grid-template-columns:1.25fr .75fr;gap:18px}.card{background:#0a1417;border:1px solid rgba(66,233,166,.15);border-radius:14px;padding:24px}.muted{color:#8ba09c}.total{font-size:34px;font-weight:900;margin:8px 0 22px}.pay{background:#0d1b1e;border:1px solid rgba(66,233,166,.18);border-radius:10px;padding:16px;margin:12px 0}.selected{border-color:#42e9a6}.badge{float:right;font-size:10px;padding:5px 9px;border-radius:12px;background:#17332b;color:#42e9a6}.btn{display:block;width:100%;border:0;border-radius:9px;padding:14px 18px;background:#42e9a6;color:#04100c;font-weight:800;cursor:pointer;margin-top:14px}.btn.secondary{background:#152326;color:#dcebe8;border:1px solid #29403d}.warn,.error,.ok{padding:13px;border-radius:9px;margin:14px 0}.warn{background:#302315;border:1px solid #67491e;color:#ffd08a}.error{background:#32191b;border:1px solid #713338;color:#ffb0b5}.ok{background:#102b23;border:1px solid #286b56;color:#8ff0c8}.back{color:#9ab0c2;text-decoration:none}.steps{display:flex;gap:8px;margin:18px 0}.step{flex:1;background:#101d20;padding:10px;border-radius:8px;color:#758b87;font-size:12px}.step.on{color:#42e9a6;border:1px solid rgba(66,233,166,.25)}.summary{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.06)}@media(max-width:760px){.grid{grid-template-columns:1fr}.wrap{margin:12px auto}.card{padding:18px}.total{font-size:28px}}</style></head><body><div class="wrap"><a class="back" href="/client">← Client Area</a><div class="steps"><div class="step on">1 · Ordre</div><div class="step on">2 · Betaling</div><div class="step">3 · Provisioning</div><div class="step">4 · Klar</div></div>@if($errors->any())<div class="error">{{$errors->first()}}</div>@endif @if(session('success'))<div class="ok">{{session('success')}}</div>@endif<div class="grid"><div class="card"><div class="muted">Sikker checkout</div><h1 style="margin-top:5px">Gennemfør betaling</h1><div class="muted">Faktura {{$invoice->number}}</div><div class="total">{{number_format((float)$invoice->total,2,',','.')}} {{$invoice->currency}}</div>@php($selected=$order?$gateways->firstWhere('gateway',$order->payment_method):null)@if($invoice->status==='paid')<div class="ok"><strong>Betalt</strong><br>Fakturaen er allerede registreret som betalt. Provisioning fortsætter automatisk.</div><a class="btn" style="text-align:center;text-decoration:none" href="/client/invoices/{{$invoice->id}}">Se faktura</a>@elseif($selected)<div class="pay selected"><span class="badge">{{$selected->test_mode?'TEST MODE':'AKTIV'}}</span><strong>{{$selected->name}}</strong><div class="muted" style="margin-top:5px">{{$selected->gateway}} · betaling verificeres server-side</div></div><form method="POST" action="/client/checkout/{{$invoice->id}}/start">@csrf<button class="btn" type="submit">Fortsæt til {{$selected->name}} →</button></form>@if(session('checkout_test'))<div class="warn"><strong>Testbetaling klar</strong><br>Gatewayen kører i testtilstand. Du kan simulere en bekræftet betaling og teste hele flowet inklusive automatisk provisioning.</div><form method="POST" action="/client/checkout/{{$invoice->id}}/test-complete">@csrf<button class="btn secondary" type="submit">Simulér godkendt testbetaling</button></form>@endif@else<div class="error">Den valgte betalingsmetode er ikke længere aktiv. Kontakt support eller opret ordren igen med en aktiv gateway.</div>@endif</div><aside class="card"><h3 style="margin-top:0">Ordreoversigt</h3><div class="summary"><span>Faktura</span><strong>{{$invoice->number}}</strong></div><div class="summary"><span>Status</span><strong>{{strtoupper($invoice->status)}}</strong></div>@if($order)<div class="summary"><span>Ordre</span><strong>#{{$order->id}}</strong></div><div class="summary"><span>Betaling</span><strong>{{strtoupper($order->payment_method)}}</strong></div>@endif<div class="summary"><span>Total</span><strong>{{number_format((float)$invoice->total,2,',','.')}} {{$invoice->currency}}</strong></div><p class="muted" style="line-height:1.6;margin-top:18px">Nodexa markerer først fakturaen som betalt efter en bekræftet betaling. Derefter sendes VPS-ordrer automatisk videre til provisioning.</p></aside></div></div></body></html>